# WinFsp system integration for Piko (install/remove).
# The package payload is the vendor MSI itself: Piko never unpacks a kernel
# driver. This script runs only after an explicit `piko system --approve-admin`
# in an Administrator terminal. install launches msiexec /i against the saved
# MSI, remove launches msiexec /x; the expected version comes from the MSI's
# own ProductVersion property, so the recipe hardcodes no version. A WinFsp
# already installed at a different version is never adopted or replaced.
param([Parameter(Mandatory = $true)][ValidateSet('install', 'remove')][string]$Action)
$ErrorActionPreference = 'Stop'
$principal = New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent())
if (-not $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
  throw 'winfsp integration must run from an Administrator terminal; Piko never opens UAC on its own'
}
$msi = Join-Path $PSScriptRoot 'winfsp.msi'
if (-not (Test-Path -LiteralPath $msi -PathType Leaf)) {
  throw ('WinFsp installer payload is missing: ' + $msi)
}
$views = @(
  'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*',
  'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*'
)
function Get-InstalledWinFsp {
  Get-ItemProperty $views -ErrorAction SilentlyContinue |
    Where-Object { $_.DisplayName -like 'WinFsp*' -and $_.DisplayVersion } |
    Sort-Object DisplayVersion -Descending | Select-Object -First 1
}
function Get-MsiProductVersion([string]$Path) {
  $installer = New-Object -ComObject WindowsInstaller.Installer
  $db = $installer.GetType().InvokeMember('OpenDatabase', 'InvokeMethod', $null, $installer, @($Path, 0))
  $view = $db.GetType().InvokeMember('OpenView', 'InvokeMethod', $null, $db, @("SELECT Value FROM Property WHERE Property='ProductVersion'"))
  $view.GetType().InvokeMember('Execute', 'InvokeMethod', $null, $view, $null) | Out-Null
  $record = $view.GetType().InvokeMember('Fetch', 'InvokeMethod', $null, $view, $null)
  if (-not $record) { throw 'WinFsp MSI has no ProductVersion property' }
  $value = $record.GetType().InvokeMember('StringData', 'GetProperty', $null, $record, @(1))
  if (-not $value) { throw 'WinFsp MSI ProductVersion is empty' }
  return $value
}
function Get-FspInstanceKeys {
  Get-ChildItem 'HKLM:\SYSTEM\CurrentControlSet\Services' -ErrorAction SilentlyContinue |
    Where-Object { $_.PSChildName -like 'WinFsp+*' } |
    Select-Object -ExpandProperty PSChildName
}
function Invoke-Msiexec([string[]]$Arguments) {
  $log = Join-Path $env:TEMP ('piko-winfsp-' + $Arguments[0].Trim('/') + '-' + (Get-Date -Format 'yyyyMMddHHmmss') + '.log')
  $exit = (Start-Process -FilePath (Join-Path $env:SystemRoot 'System32\msiexec.exe') -ArgumentList ($Arguments + @('/qn', '/norestart', '/l*v', ('"' + $log + '"'))) -Wait -PassThru).ExitCode
  if ($exit -notin 0, 3010, 1641) {
    throw ('msiexec ' + $Arguments[0] + ' failed (exit ' + $exit + '); log: ' + $log)
  }
  Write-Host ('msiexec ' + $Arguments[0] + ' exit ' + $exit + '; log ' + $log)
}
$expected = Get-MsiProductVersion $msi
$installed = Get-InstalledWinFsp
if ($Action -eq 'install') {
  if ($installed -and $installed.DisplayVersion -ne $expected) {
    throw ('Installed WinFsp ' + $installed.DisplayVersion + ' does not match the managed MSI ' + $expected + '; remove it via Windows Apps & features first')
  }
  if (-not $installed) {
    Invoke-Msiexec @('/i', ('"' + $msi + '"'))
    $installed = Get-InstalledWinFsp
  }
  if (-not $installed) { throw 'WinFsp is not registered after installation' }
  if ($installed.DisplayVersion -ne $expected) {
    throw ('Registered WinFsp ' + $installed.DisplayVersion + ' does not match the managed MSI ' + $expected)
  }
  if (-not (Get-Service -Name 'WinFsp.Launcher' -ErrorAction SilentlyContinue)) {
    throw 'WinFsp.Launcher service is missing after installation'
  }
  $instances = @(Get-FspInstanceKeys)
  if (-not $instances.Count) {
    throw 'WinFsp FSD instance service key (WinFsp+*) is missing after installation'
  }
  Write-Host ('WinFsp ' + $expected + ' installed: FSD instance ' + ($instances -join ', ') + '; WinFsp.Launcher service present')
} else {
  if (-not $installed) {
    Write-Host 'No registered WinFsp found; nothing to remove'
    return
  }
  if ($installed.DisplayVersion -ne $expected) {
    throw ('Installed WinFsp ' + $installed.DisplayVersion + ' is not the version managed by this package (' + $expected + '); refusing to remove it')
  }
  Invoke-Msiexec @('/x', ('"' + $msi + '"'))
  if (Get-InstalledWinFsp) { throw 'WinFsp is still registered after removal' }
  if (Get-Service -Name 'WinFsp.Launcher' -ErrorAction SilentlyContinue) { throw 'WinFsp.Launcher service is still present after removal' }
  $remaining = @(Get-FspInstanceKeys)
  if ($remaining.Count) { throw ('WinFsp FSD instance keys remain after removal: ' + ($remaining -join ', ')) }
  Write-Host ('WinFsp ' + $expected + ' removed')
}
